select (select count(*) from supabase_migrations.schema_migrations) as migrations, (select count(*) from auth.users) as synthetic_users, (select count(*) from auth.users where email !~ '^finzi-staging-[0-9a-f-]+-[ab]@example.test$') as unexpected_users, (select count(*) from storage.objects) as synthetic_objects, (select count(*) from pg_roles r cross join pg_namespace n where r.rolname in ('app_executor','finzi_deletion_worker','finzi_telegram_gateway') and n.nspname in ('finance','api','ops','telegram_private') and has_schema_privilege(r.rolname,n.oid,'CREATE')) as runtime_schema_create_grants, (select count(*) from (select t.id from finance.transactions t left join finance.transaction_entries e on e.user_id=t.user_id and e.transaction_id=t.id group by t.id,t.kind,t.amount having (t.kind='transfer' and (count(e.transaction_id)<>2 or coalesce(sum(e.signed_amount),0)<>0 or count(*) filter(where abs(e.signed_amount)=t.amount)<>2)) or (t.kind<>'transfer' and (count(e.transaction_id)<>1 or coalesce(sum(e.signed_amount),0)<>case when t.kind='income' then t.amount else -t.amount end))) invalid) as invalid_ledger_transactions;
